package com.opspilot.task.dto; import java.time.*; import com.opspilot.task.*; public record TaskResponse(Long id,Long projectId,String title,String description,TaskStatus status,TaskPriority priority,TaskUserResponse assignee,TaskUserResponse creator,LocalDate dueDate,Instant createdAt,Instant updatedAt){public static TaskResponse from(Task t){return new TaskResponse(t.getId(),t.getProject().getId(),t.getTitle(),t.getDescription(),t.getStatus(),t.getPriority(),TaskUserResponse.from(t.getAssignee()),TaskUserResponse.from(t.getCreatedBy()),t.getDueDate(),t.getCreatedAt(),t.getUpdatedAt());}}
